};
$toxincategorycheck = static function(array $herb): bool {
    return (int) ($herb['primarycategory'] ?? 0) === 6;
};
$toxinherbs = array_values(array_filter($toxinherbs, static function(array $herb) use ($toxinguidelinecheck, $toxincategorycheck): bool {
