    ['question' => $toxintext('Which throat herb is chosen when Phlegm and wheezing dominate?', '¿Qué hierba de garganta se elige cuando dominan Flema y sibilancias?'), 'answer' => $toxintext('She Gan. Shan Dou Gen is stronger for severe toxic swelling; Ma Bo is lighter and more dispersing for Wind-Heat.', 'She Gan. Shan Dou Gen es más fuerte para inflamación tóxica grave; Ma Bo es más ligera y dispersante para Viento-Calor.')],
    ['question' => $toxintext('How do internal abscess herbs differ by location?', '¿Cómo se diferencian las hierbas para abscesos internos según localización?'), 'answer' => $toxintext('Pu Gong Ying favors breast and Liver/Stomach clumps; Yu Xing Cao favors Lung abscess and pus; Bai Jiang Cao favors intestinal or pelvic abscess with Blood stasis; Lu Gen adds fluid generation in Lung abscess.', 'Pu Gong Ying favorece mama y masas Hígado/Estómago; Yu Xing Cao favorece absceso pulmonar y pus; Bai Jiang Cao favorece absceso intestinal o pélvico con estasis de Sangre; Lu Gen añade generación de líquidos en absceso pulmonar.')],
    ['question' => $toxintext('Why is He Ye an exception in this module?', '¿Por qué He Ye es una excepción en este módulo?'), 'answer' => $toxintext('The current module title includes it, but Bensky primarily places He Ye with Summerheat herbs. Its testable identity is Summerheat clearing, raising clear Yang and stopping bleeding—not broad Heat-toxin resolution.', 'El título actual del módulo la incluye, pero Bensky sitúa He Ye principalmente con hierbas para Calor de Verano. Su identidad examinable es aclarar Calor de Verano, elevar Yang claro y detener sangrado, no resolver ampliamente Calor-Toxina.')],
];

?>
<section class="single-herbs-guide__section" aria-labelledby="topic-six-foundations"><h4 id="topic-six-foundations"><?php echo s($toxintext('Herbs that Clear Heat and Resolve Toxicity: general introduction', 'Hierbas que aclaran Calor y resuelven toxicidad: introducción general')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($toxintext('These herbs treat concentrated Heat-toxin expressed as red, hot, painful swelling, pus, abscess, ulceration or severe throat inflammation. The decisive Board skill is matching the toxic process to its location.', 'Estas hierbas tratan Calor-Toxina concentrado expresado como inflamación roja, caliente y dolorosa, pus, absceso, ulceración o inflamación grave de garganta. La habilidad Board decisiva es relacionar el proceso tóxico con su localización.')); ?></p><div class="single-herbs-guide__pattern"><article><strong><?php echo s($toxintext('Typical presentation', 'Presentación típica')); ?></strong><span><?php echo s($toxintext('Redness, swelling, heat, pain, pus, sore throat, abscess or toxic rash with a red tongue and rapid pulse.', 'Enrojecimiento, inflamación, calor, dolor, pus, garganta dolorosa, absceso o erupción tóxica con lengua roja y pulso rápido.')); ?></span></article><article><strong><?php echo s($toxintext('Choose by location', 'Elige por localización')); ?></strong><span><?php echo s($toxintext('Broad/exterior, Heart clump, breast, Summerheat, phlegmy throat or severe toxic throat.', 'Amplio/exterior, masa de Corazón, mama, Calor de Verano, garganta con Flema o garganta tóxica grave.')); ?></span></article><article><strong><?php echo s($toxintext('Safety boundary', 'Límite de seguridad')); ?></strong><span><?php echo s($toxintext('Abscess, airway swelling, high fever or systemic toxicity requires biomedical assessment; this guide teaches recognition, not self-treatment.', 'Absceso, inflamación de vía aérea, fiebre alta o toxicidad sistémica requiere evaluación biomédica; esta guía enseña reconocimiento, no autotratamiento.')); ?></span></article></div><p class="single-herbs-guide__scope-note"><strong><?php echo s($toxintext('General precautions:', 'Precauciones generales:')); ?></strong> <?php echo s($toxintext('most are cold and may injure Spleen/Stomach Yang when overused. Strong throat herbs require particular dose care. Distinguish true Heat-toxin from deficient, chronic or already-draining lesions.', 'la mayoría son frías y pueden lesionar Yang de Bazo/Estómago si se usan en exceso. Las hierbas fuertes para garganta requieren especial cuidado de dosis. Distingue Calor-Toxina verdadero de lesiones deficientes, crónicas o ya drenando.')); ?></p><aside class="single-herbs-guide__memory-path" aria-label="<?php echo s($toxintext('Toxicity response team memory path', 'Recorrido mnemotécnico del equipo contra toxicidad')); ?>"><p class="single-herbs-guide__memory-line"><?php echo s($toxintext('The house now sounds a toxicity alarm. Ten official responders take different rooms.', 'La casa activa una alarma de toxicidad. Diez respondedores oficiales ocupan cuartos distintos.')); ?></p><p><?php echo s($toxintext('Jin Yin Hua patrols outside and inside; Lian Qiao breaks the Heart-room knot; Pu Gong Ying treats the breast wing; He Ye opens the summer umbrella; She Gan clears phlegmy throat pipes; Shan Dou Gen extinguishes the most toxic throat fire; Yu Xing Cao drains pus from the Lung room; Bai Jiang Cao clears the intestinal-pelvic room; Bai Hua She She Cao washes toxicity through urine; Tu Fu Ling filters toxic Dampness from sores and joints.', 'Jin Yin Hua patrulla afuera y adentro; Lian Qiao rompe el nudo del cuarto de Corazón; Pu Gong Ying atiende el ala mamaria; He Ye abre el paraguas de verano; She Gan limpia tuberías de garganta con Flema; Shan Dou Gen apaga el fuego tóxico más intenso de garganta; Yu Xing Cao drena pus del cuarto de Pulmón; Bai Jiang Cao limpia el cuarto intestinal-pélvico; Bai Hua She She Cao elimina toxicidad mediante la orina; Tu Fu Ling filtra Humedad tóxica de lesiones y articulaciones.')); ?></p><p><strong><?php echo s($toxintext('Same alarm, different room.', 'Misma alarma, cuarto diferente.')); ?></strong></p></aside><h5 class="single-herbs-guide__catalog-heading"><?php echo s($toxintext('Current Board category herbs', 'Hierbas de la categoría Board vigente')); ?></h5><p class="single-herbs-guide__catalog-intro"><?php echo s($toxintext('Study these ten official herbs as Category 6. Each one satisfies both required conditions: it is in the current guideline 2026 and its primary classification is Herbs that Clear Heat and Resolve Toxicity.', 'Estudia estas diez hierbas oficiales como Categoría 6. Cada una cumple ambas condiciones requeridas: está en el guideline 2026 vigente y su clasificación primaria es Hierbas que aclaran Calor y resuelven toxicidad.')); ?></p><ol class="single-herbs-guide__category-herbs"><?php foreach ($toxinherbs as $categoryherb): ?><li class="single-herbs-guide__category-herb single-herbs-guide__category-herb--core"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($categoryherb['name']); ?></strong><em><?php echo s($categoryherb['latin']); ?></em><span class="single-herbs-guide__category-herb-badge"><?php echo s($toxintext('In current guideline 2026 · Category 6', 'En el guideline 2026 vigente · Categoría 6')); ?></span></div><p><?php echo s($categoryherb['identity']); ?></p></li><?php endforeach; ?></ol></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-six-yang-title"><h4 id="topic-six-yang-title"><?php echo s($toxintext('Yang comparative fingerprint', 'Huella comparativa de Yang')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($toxintext('The figures separate dispersing strength from organ location. Values are relative study indices, not clinical percentages.', 'Las figuras separan fuerza dispersante de localización orgánica. Los valores son índices relativos de estudio, no porcentajes clínicos.')); ?></p><div class="single-herbs-guide__yang-charts"><?php foreach ($toxincharts as $chart): ?><article class="single-herbs-guide__yang-chart"><h5><?php echo s($chart['title']); ?></h5><small><?php echo s($chart['figure']); ?></small><?php foreach ($chart['items'] as $herbname => $value): ?><div class="single-herbs-guide__yang-bar"><span><?php echo s($herbname); ?></span><span class="single-herbs-guide__yang-bar-track"><span class="single-herbs-guide__yang-bar-fill" style="width:<?php echo (int) $value; ?>%"></span></span><b><?php echo (int) $value; ?></b></div><?php endforeach; ?></article><?php endforeach; ?></div><p class="single-herbs-guide__yang-note"><strong><?php echo s($toxintext('Reading rule:', 'Regla de lectura:')); ?></strong> <?php echo s($toxintext('Jin Yin Hua and Lian Qiao share broad dispersing power; the remaining choice becomes anatomical—Stomach/breast, Lung with Phlegm, or the intensely toxic throat.', 'Jin Yin Hua y Lian Qiao comparten potencia dispersante amplia; la elección restante se vuelve anatómica: Estómago/mama, Pulmón con Flema o garganta intensamente tóxica.')); ?></p></section>

